part of 'theme.dart';

/// Generated by Forui CLI, enhanced with tabular figures for all numeric content.
///
/// Typography tokens for the generated theme.
FTypography _typography({required FColors colors, required bool touch}) {
  final headingFamily = GoogleFonts.plusJakartaSans().fontFamily!;
  final bodyFamily = GoogleFonts.inter().fontFamily!;
  return FTypography(
    display: _display(colors: colors, touch: touch, fontFamily: headingFamily),
    body: _body(colors: colors, touch: touch, fontFamily: bodyFamily),
  );
}

TextStyle _typefaceStyle({
  required Color color,
  required String fontFamily,
  required double fontSize,
  required double height,
  List<String>? fontFamilyFallback,
}) {
  return TextStyle(
    color: color,
    fontFamily: fontFamily,
    fontFamilyFallback: fontFamilyFallback,
    fontSize: fontSize,
    height: height,
    leadingDistribution: TextLeadingDistribution.even,
    fontFeatures: const [FontFeature.tabularFigures()],
  );
}

/// The typographical tokens used for prominent text such as headings.
FTypeface _display({
  required FColors colors,
  required bool touch,
  String fontFamily = FTypeface.defaultFontFamily,
  List<String>? fontFamilyFallback,
}) {
  assert(
    fontFamily.isNotEmpty,
    'fontFamily ($fontFamily) should not be empty.',
  );
  final color = colors.foreground;
  if (touch) {
    return FTypeface(
      fontFamily: fontFamily,
      fontFamilyFallback: fontFamilyFallback,
      xs3: _typefaceStyle(
        color: color,
        fontFamily: fontFamily,
        fontFamilyFallback: fontFamilyFallback,
        fontSize: 10,
        height: 1,
